actions.recordExtractor:
({ $, url }) => {
  // Nextra 3 (App Router) renders page content inside <main>.
  // The article selector used by the legacy Nextra 2 config does not
  // match because there is no <article> element in the Nextra 3 layout.
  const contentEl = $('main .nextra-content, main article, main');
  const content = contentEl.first().text().trim();

  // Extract page title from h1 (Nextra renders the MDX title as h1),
  // falling back to the <title> element.
  const title = $('h1').first().text().trim()
    || $('title').text().replace(' | ILN Docs', '').trim();

  // Extract the meta description injected by Next.js.
  const description =
    $('meta[name="description"]').attr('content') ||
    $('meta[property="og:description"]').attr('content') ||
    '';

  // Derive section from the URL path for faceting in the search UI.
  const pathname = new URL(url).pathname.replace(/\/$/, '');
  const segments = pathname.split('/').filter(Boolean);
  const section = segments.length > 0 ? segments[0] : 'home';

  // Collect all h2/h3 anchors on the page for sub-section records.
  const records = [];

  // One top-level record for the full page.
  records.push({
    objectID: url,
    type: 'page',
    url,
    title,
    description,
    section,
    content: content.slice(0, 5000)
  });

  // One record per h2 heading for granular search results.
  $('main h2').each((_, el) => {
    const headingText = $(el).text().trim();
    const anchor = $(el).attr('id') || '';
    if (!headingText) return;
    records.push({
      objectID: anchor ? `${url}#${anchor}` : `${url}#${headingText}`,
      type: 'heading',
      url: anchor ? `${url}#${anchor}` : url,
      title: headingText,
      section,
      hierarchy: { lvl0: title, lvl1: headingText }
    });
  });

  return records;
}
